module top_module(
  input clk,
  input rst_n,
  input [255:0] in,
  input [7:0] sel,
  input valid_a,
  input ready_b,
  output reg ready_a, // Change to reg
  output reg valid_b,
  output reg [9:0] data_out
);// 256-to-1 multiplexer
  wire [255:0] mux_out;
  assign mux_out = in[sel];

  // Accumulator
  reg [7:0] acc_reg;
  reg [2:0] acc_count;
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      acc_reg <= 8'h00;
      acc_count <= 3'b000;
    end else if (valid_a && ready_a) begin
      acc_reg <= acc_reg + mux_out[7:0];
      acc_count <= acc_count + 1;
    end
  end

  // Output final result
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      valid_b <= 1'b0;
      data_out <= 10'h000;
    end else if (acc_count == 3'b111) begin
      valid_b <= 1'b1;
      data_out <= {1'b0, acc_reg};
      acc_reg <= 8'h00;
      acc_count <= 3'b000;
    end else begin
      valid_b <= 1'b0;
      data_out <= 10'h000;
    end
  end

  // Valid-ready handshake
  reg valid_a_reg;
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      valid_a_reg <= 1'b0;
      ready_a <= 1'b0;
    end else if (valid_a && ready_a) begin
      valid_a_reg <= 1'b1;
      ready_a <= 1'b0;
    end else if (!valid_a_reg && ready_a) begin
      ready_a <= 1'b1;
    end else if (valid_b && !ready_b) begin
      ready_a <= 1'b0;
    end
  end

endmodule

