module top_module(
  input data_in,
  input clk_in,
  output reg data_out,
  output reg clk_out
);reg [31:0] counter;
  reg [31:0] phase_adjust;
  reg [31:0] phase_accumulator;
  reg [31:0] phase_step;

  always @(posedge clk_in) begin
    counter <= counter + 1;
    if (data_in) begin
      phase_adjust <= counter;
    end
  end

  always @(posedge clk_in) begin
    phase_accumulator <= phase_accumulator + phase_step;
    if (phase_accumulator < phase_adjust) begin
      clk_out <= ~clk_out;
    end
  end

  always @(posedge clk_in) begin
    if (clk_out) begin
      data_out <= data_in;
    end
  end

  initial begin
    counter <= 0;
    phase_adjust <= 0;
    phase_accumulator <= 0;
    phase_step <= 32'h80000000;
    data_out <= 0;
    clk_out <= 0;
  end

endmodule

