output	[3-1:0] ALUOp_o;
output			ALUSrc_o;
output			RegDst_o;


wire	[3-1:0] ALUOp_o;
wire			ALUSrc_o;
wire			RegWrite_o;
wire			RegDst_o;



reg	[3-1:0] aluOp_o;
reg	aluSrc_o;
reg	regWrite_o;
reg	regDst_o;

