			aluSrc_o = 1;
			regWrite_o = 1;
			regDst_o = 0;
		end
	endcase
end

assign ALUOp_o = aluOp_o;
assign ALUSrc_o = aluSrc_o;
assign RegWrite_o = regWrite_o;
assign RegDst_o = regDst_o;

endmodule

