module sequence_detector (
    input clk,
    input in,
    input reset,
    output sequence_found);parameter S0=0, S1=1, S11=2, S111=3, S1110=4;
    reg [2:0] state;
    reg [2:0] next;

    always_comb begin
        case (state)
            S0: next = in ? S1 : S0;
            S1: next = in ? S11 : S0;
            S11: next = in ? S111 : S0;
            S111: next = in ? S111 : S1110;
            S1110: next = in ? S1 : S0;
        endcase
    end

    always @(posedge clk) begin
        if (reset) state <= S0;
        else state <= next;
    end

    assign sequence_found = (state == S1110);

endmodule

