        endtask

    task testcase002;

    begin
        test_num = test_num + 1;
        $display("Test Case %0d: Toggle once (0 -> 1)", test_num);
        reset_dut();
        @(negedge Clock);
        Enable = 1;
        S = 1;
        @(negedge Clock);
        #1;
        #1;

        check_outputs(1'b1);
    end
        endtask

    task testcase003;

    begin
        test_num = test_num + 1;
        $display("Test Case %0d: Toggle twice (0 -> 1 -> 0)", test_num);
        reset_dut();
        @(negedge Clock);
        Enable = 1;
        S = 1;
        @(negedge Clock);
        @(negedge Clock);
        #1;
        #1;

        check_outputs(1'b0);
