module top_module(
    input [31:0] data,
    input inclock,
    input outclock,
    input outclocken,
    output reg [31:0] q,  // Changed 'output' to 'output reg' 
    input [4:0] rdaddress,
    input [4:0] wraddress,
    input wren
);parameter DEPTH = 16;
    parameter WIDTH = 32;

    reg [WIDTH-1:0] mem [DEPTH-1:0];
    reg [4:0] read_ptr, write_ptr;
    reg empty, full;

    always @(posedge inclock) begin
        if (wren && !full) begin
            mem[write_ptr] <= data;
            write_ptr <= (write_ptr == DEPTH-1) ? 0 : write_ptr + 1;
        end
        full <= (write_ptr == read_ptr && wren);
        empty <= (write_ptr == read_ptr && !wren);
    end

    always @(posedge outclock) begin
        if (outclocken && !empty) begin
            q <= mem[read_ptr];
            read_ptr <= (read_ptr == DEPTH-1) ? 0 : read_ptr + 1;
        end
        // Eliminated redundant full and empty assignments here
    end

endmodule

