description:
Implement the Verilog module based on the following description.
Build a 12-bit binary counter with asynchronous active low reset signal and a preset enable signal. When preset is high, preset the counter with the provided value.
// (1) reset_n: Resets the counter to 12'b000000000000 when low.
// (2) preset: Enables the preset operation when high.
// (3) preset_val: The value to be preset into the counter when preset is high.
// (4) q: The value of the counter.

module top_module(
    input clk,
    input reset_n,
    input preset,
    input [11:0] preset_val,
    output reg [11:0] q);

code:
module top_module(
    input clk,
    input reset_n,
    input preset,
    input [11:0] preset_val,
    output reg [11:0] q
);

    always @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            // Asynchronous reset: Reset the counter to 12'b000000000000
            q <= 12'b000000000000;
        end else if (preset) begin
            // Preset operation: Preset the counter with the provided value
            q <= preset_val;
        end else begin
            // Binary counter: Increment by 1
            q <= q + 1;
        end
    end

endmodule

